@router.get('/books/search')
def search_books(q: str):
    conn = get_connection()
    rows = conn.execute(f"SELECT * FROM books WHERE title LIKE '%{q}%'").fetchall()
    return [dict(r) for r in rows]

@router.get('/books')
def list_books():
    return [dict(r) for r in get_connection().execute('SELECT * FROM books').fetchall()]

FINE_PER_DAY = 5  # rupees
MAX_FINE = 500

def calculate_fine(due: date, returned: date) -> int:
    days_late = (returned - due).days
    return min(days_late * FINE_PER_DAY, MAX_FINE)
